message.content:
{
  "description": "The creature is a large quadrupedal animal shown in right-facing profile against a plain off-white background, with the overall body shape, dense shaggy fur, head, limbs and paws of a bear combined with several glossy, hard, dark reddish-brown structures resembling a beetle. It stands on four thick, furry legs with a short stubby tail at the rear and a bear-like head at the front bearing a single large curved black horn on the forehead. Most of the body is covered in long brown fur that is darker on the legs and lighter on the muzzle and along the mid-side, while the mid-back, shoulder-chest, and outer hindquarter are covered by smooth, shiny, ridged plates, the lower legs are encircled by narrow segmented bands, and two horizontal rows of small oval holes run along the side of the torso.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head with dense brown fur, lighter tan fur on the muzzle, a large black nose at the tip, small brown eyes, and a closed mouth, viewed in profile facing right",
      "where": "at the front end of the body, in front of the shoulder plate"
    },
    {
      "part": "horns",
      "looks_like": "single large glossy black horn, smooth and curved backward with a small pointed notch on the front edge near the tip, with a rounded base",
      "where": "rising vertically from the center of the forehead between the ears"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears covered in brown fur, with slightly darker edges",
      "where": "on top of the head, one on each side of the horn base"
    },
    {
      "part": "legs",
      "looks_like": "four thick columnar legs covered in long shaggy dark brown fur, muscular and straight",
      "where": "under the body, two forelegs under the chest and two hindlegs under the hips, supporting the body in a standing quadrupedal stance"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws with thick fur and visible long dark claws at the toe tips",
      "where": "at the bottom end of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "very short, stubby, furry protrusion, same brown fur as the hindquarters",
      "where": "at the rear of the body, on the leftmost end"
    },
    {
      "part": "shell",
      "looks_like": "glossy hard exoskeleton-like shell, dark reddish-brown to black, smooth and shiny with fine longitudinal ridges and a central seam on some pieces",
      "where": "as large coverings over the mid-back, over the shoulder and upper chest, and over the outer hind thigh"
    },
    {
      "part": "plates",
      "looks_like": "several distinct hardened plates: a large oval ridged plate covering the mid-back, a smaller oval plate with a central line on the outer hind leg, a large shield-shaped plate with a pointed dorsal projection covering the shoulders and chest with small spiky projections along its lower edge, and narrow segmented dark bands encircling each lower leg just above and below the joints",
      "where": "mid-back plate on the dorsal midline, hip plate on the side of the hindquarter, shoulder plate draped over the front of the torso, and bands around all four lower legs"
    },
    {
      "part": "markings",
      "looks_like": "two horizontal rows of small oval holes with pale rims, resembling spiracles, set in a patch of lighter tan fur",
      "where": "along the side of the torso, one row just below the mid-back plate and one row lower on the flank, between the fore and hind legs"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "rhinoceros beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
